import requests
from bs4 import BeautifulSoup
import sys

def get_city_name(lat, lon):
    query = f"{lat} {lon} city name"
    search_url = f"https://www.google.com/search?q={query.replace(' ', '+')}&tbm=isch"

    try:
        response = requests.get(search_url, timeout=10)
        soup = BeautifulSoup(response.text, 'html.parser')

        # Extract city name from search results
        for item in soup.find_all('div', class_='r'):
            link = item.find('a')
            if link:
                href = link.get('href')
                if href and 'maps' in href:
                    return href.split('q=')[1].split('&')[0].replace('+', ' ')
        return "Unknown"
    except Exception as e:
        return f"Error: {str(e)}"


def main():
    if len(sys.argv) < 2:
        print("Usage: python temperature_analysis.py <csv_file> <keyword>")
        return

    csv_file = sys.argv[1]
    keyword = sys.argv[2] if len(sys.argv) > 2 else ""

    try:
        # Read CSV file
        df = pd.read_csv(csv_file)

        # Calculate average temperature per city
        avg_temp = df.groupby(['city'])['temperature'].mean().reset_index()

        # Get city names from coordinates
        city_names = []
        for _, row in avg_temp.iterrows():
            lat = row['latitude']
            lon = row['longitude']
            city_name = get_city_name(lat, lon)
            city_names.append(f"{city_name} (Avg Temp: {row['temperature']:.2f})")

        # Write to output file
        with open('/tmp/city_temperature_info.txt', 'w') as f:
            for name in city_names:
                f.write(name + '\n')

        # Check keyword match
        if keyword:
            matched = any(keyword in name for name in city_names)
            print(f"Keyword '{keyword}' found in city names: {matched}")
        else:
            print("No keyword provided for matching.")
    except Exception as e:
        print(f"Error: {str(e)}")

if __name__ == "__main__":
    main()"
