import pandas as pd
import logging
from datetime import datetime

# Configure logging
directory = '/tmp'
logging.basicConfig(
    filename=f'{directory}/stock_data.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    filemode='w'
)

logger = logging.getLogger(__name__)

API_URL = "https://www.alphavantage.co/query"
API_KEY = "YOUR_API_KEY_HERE"  # Replace with your Alpha Vantage API key


def fetch_stock_data(symbol, interval='daily', output_size=100):
    """Fetch historical stock data from Alpha Vantage API"""
    try:
        params = {
            "function": f"TIME_SERIES_{interval.upper()}",
            "symbol": symbol,
            "interval": interval,
            "output_size": output_size,
            "apikey": API_KEY
        }

        logger.info(f"Fetching data for {symbol} ({interval} interval)")
        response = requests.get(API_URL, params=params, timeout=10)
        response.raise_for_status()

        data = response.json()

        # Check for API errors
        if "Error Message" in data:
            logger.error(f"API Error: {data["Error Message"]}")
            return pd.DataFrame()

        # Extract time series data
        time_series = data[f"TIME_SERIES_{interval.upper()}"]

        # Convert to DataFrame
        df = pd.DataFrame.from_dict(time_series, orient='index')
        df.index = pd.to_datetime(df.index)
        df = df.sort_index()

        # Rename columns for clarity
        df.columns = [col.lower() for col in df.columns]

        logger.info(f"Successfully fetched {len(df)} data points")
        return df
    except requests.exceptions.RequestException as e:
        logger.error(f"Request failed: {str(e)}")
        return pd.DataFrame()
    except Exception as e:
        logger.error(f"Unexpected error: {str(e)}")
        return pd.DataFrame()


def calculate_daily_returns(df):
    """Calculate daily returns from closing prices"""
    try:
        if df.empty:
            logger.warning("No data to process")
            return pd.DataFrame()

        # Ensure we have closing prices
        if "close" not in df.columns:
            logger.warning("Missing 'close' column in data")
            return pd.DataFrame()

        # Calculate daily returns
        df["daily_return"] = df["close"].pct_change()

        # Drop NaN values
        df = df.dropna()

        logger.info(f"Calculated daily returns for {len(df)} data points")
        return df
    except Exception as e:
        logger.error(f"Error calculating returns: {str(e)}")
        return pd.DataFrame()


def save_to_csv(df, filename="stock_returns.csv"):
    """Save processed data to CSV file"""
    try:
        if df.empty:
            logger.warning("No data to save")
            return

        output_path = f"{directory}/{filename}"
        df.to_csv(output_path, index=True)
        logger.info(f"Saved {len(df)} records to {output_path}")
    except Exception as e:
        logger.error(f"Error saving to CSV: {str(e)}")


def main():
    """Main execution function"""
    try:
        # Example: Fetch Apple Inc. (AAPL) daily data
        stock_symbol = "AAPL"

        raw_data = fetch_stock_data(stock_symbol)
        processed_data = calculate_daily_returns(raw_data)
        save_to_csv(processed_data)

        logger.info("Processing completed successfully")
    except Exception as e:
        logger.error(f"Main execution failed: {str(e)}")

if __name__ == "__main__":
    main()"
