import sys

def compute_hash(file_path, chunk_size=8192):
    """Compute SHA-256 hash of a file."""
    hash_algo = hashlib.sha256()
    with open(file_path, 'rb') as f:
        while chunk := f.read(chunk_size):
            hash_algo.update(chunk)
    return hash_algo.hexdigest()


def find_duplicates(root_dir):
    """Find duplicate files by their hash."""
    hashes = {}
    duplicates = {}

    for dirpath, _, filenames in os.walk(root_dir):
        for filename in filenames:
            file_path = os.path.join(dirpath, filename)

            # Skip directories and special files
            if os.path.isdir(file_path) or not os.path.isfile(file_path):
                continue

            # Skip files with no read permissions
            if not os.access(file_path, os.R_OK):
                continue

            try:
                file_hash = compute_hash(file_path)
            except Exception as e:
                print(f"Error reading {file_path}: {str(e)}")
                continue

            if file_hash in hashes:
                # Add to duplicates
                if file_hash not in duplicates:
                    duplicates[file_hash] = [hashes[file_hash]]
                duplicates[file_hash].append(file_path)
            else:
                hashes[file_hash] = file_path

    return duplicates


def deduplicate_files(duplicates):
    """Replace duplicate files with hard links."""
    total_saved = 0

    for file_hash, files in duplicates.items():
        if len(files) < 2:
            continue

        # Keep the first file as the original
        original_file = files[0]

        # For all other files, replace with hard link
        for duplicate_file in files[1:]:
            try:
                os.link(original_file, duplicate_file)
                print(f"Replaced {duplicate_file} with hard link to {original_file}")
                total_saved += os.path.getsize(duplicate_file)
            except Exception as e:
                print(f"Failed to replace {duplicate_file}: {str(e)}")

    print(f"
Total space saved: {total_saved // (1024 * 1024)} MB")


def main():
    if len(sys.argv) != 2:
        print("Usage: python deduplication_tool.py <directory>")
        sys.exit(1)

    root_dir = os.path.abspath(sys.argv[1])
    print(f"Scanning directory: {root_dir}")

    try:
        duplicates = find_duplicates(root_dir)
        if not duplicates:
            print("No duplicate files found.")
            return

        print(f"Found {len(duplicates)} duplicate groups:")
        for i, (file_hash, files) in enumerate(duplicates.items(), 1):
            print(f"Group {i}: {len(files)} files with hash {file_hash[:10]}...")

        if input("\nProceed with deduplication? (y/n): ").lower() == 'y':
